INSERT INTO `chat_messages` VALUES (1,1,'ai','您好！我是心理健康辅助AI助手。我可以帮助您了解心理健康知识、解答关于抑郁症和焦虑症的问题，以及引导您使用心理量表评估自己的心理状态。请问有什么我可以帮助您的吗？','text',NULL,0,0,NULL,'deep_think',NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,NULL,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(2,1,'user','抑郁症有哪些典型症状？','text',NULL,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,NULL,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(3,2,'ai','您好！我是您的自杀风险评估助手。我可以帮助您分析文本中的风险信号，提供专业建议。请上传需要分析的文本内容。','text',NULL,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,NULL,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(4,2,'user','如何识别自杀风险信号？','text',NULL,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,NULL,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(5,3,'ai','您好！我是危机干预助手。当您感到困难时，请记住您并不孤单。以下是一些可以立即获得的帮助资源...','text',NULL,0,0,NULL,'intervention',NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,NULL,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(6,3,'user','有什么心理援助资源可以推荐？','text',NULL,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,NULL,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(7,3,'ai','以下是一些可用的心理援助资源：\n\n1. 全国心理援助热线：400-161-9995（24小时）\n2. 北京心理危机研究与干预中心：010-82951332\n3. 生命热线：400-821-1215\n\n如果您正处于紧急危机中，请立即拨打这些热线或联系当地的紧急服务。','text',NULL,0,0,NULL,'intervention',NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,NULL,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(8,3,'user','好的，谢谢。','text',NULL,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,NULL,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(9,1,'ai','您好！我是心理健康辅助AI助手。我可以帮助您了解心理健康知识、解答关于抑郁症和焦虑症的问题，以及引导您使用心理量表评估自己的心理状态。请问有什么我可以帮助您的吗？','text',NULL,0,0,NULL,'deep_think',NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,NULL,'2026-04-19 22:39:06','2026-04-19 22:39:06'),(10,1,'user','抑郁症有哪些典型症状？','text',NULL,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,NULL,'2026-04-19 22:39:06','2026-04-19 22:39:06'),(11,2,'ai','您好！我是您的自杀风险评估助手。我可以帮助您分析文本中的风险信号，提供专业建议。请上传需要分析的文本内容。','text',NULL,0,0,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,NULL,NULL,NULL,'2026-04-19 22:39:06','2026-04-19 22:39:06'),(12,2,'user','如何识别自杀风险信号？','text',N