CREATE TABLE `chat_recommended_questions` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `question` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题内容',
  `ai_mode` enum('deep_think','risk_assessment','intervention','scale_interpret','all') COLLATE utf8mb4_unicode_ci DEFAULT 'all' COMMENT '适用AI模式',
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '问题分类',
  `keywords` json DEFAULT NULL COMMENT '关键词',
  `sort_order` int DEFAULT '0' COMMENT '排序顺序',
  `usage_count` int DEFAULT '0' COMMENT '使用次数',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_ai_mode` (`ai_mode`),
  KEY `idx_category` (`category`),
  KEY `idx_sort_order` (`sort_order`),
  KEY `idx_usage_count` (`usage_count`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='推荐问题表';
/*!40101 SET character_set_client = @saved_cs_client */;

