DROP TABLE IF EXISTS `chat_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `chat_sessions` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `session_code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '会话编号',
  `user_id` bigint DEFAULT NULL COMMENT '关联用户ID',
  `user_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脱敏用户标识',
  `archive_id` bigint DEFAULT NULL COMMENT '关联档案ID',
  `data_source` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据来源',
  `ai_mode` enum('deep_think','risk_assessment','intervention','scale_interpret') COLLATE utf8mb4_unicode_ci DEFAULT 'deep_think' COMMENT 'AI模式',
  `context_type` enum('general','knowledge_base','archive','scale') COLLATE utf8mb4_unicode_ci DEFAULT 'general' COMMENT '上下文类型',
  `knowledge_sources` json DEFAULT NULL COMMENT '知识库来源',
  `rag_keywords` json DEFAULT NULL COMMENT 'RAG检索关键词',
  `message_count` int DEFAULT '0' COMMENT '消息数量',
  `total_tokens` int DEFAULT '0' COMMENT '总Token数',
