INSERT INTO `knowledge_documents` VALUES (1,'事后干预与随访',4,75,'[\"事后干预\", \"随访\", \"危机后\", \"支持计划\", \"风险追踪\", \"团队协作\", \"康复\", \"复发自杀预防\"]','md','事后干预与随访.md','/rag-skill/knowledge/危机干预/事后干预与随访/事后干预与随访.md',6324,'6.2 KB','自杀危机事后干预与随访指南，包括危机后心理支持、随访时间线（24-48小时、1周、2周、1/3/6个月）、风险追踪、团队协作及长期康复支持。WHO数据显示及时随访可将重复自伤风险降低50%。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(2,'全国心理危机热线',4,73,'[\"热线\", \"12356\", \"心理援助\", \"即时求助\", \"危机干预\", \"全国热线\", \"省市热线\", \"危机电话\", \"自杀求助\"]','txt','全国心理危机热线.txt','/rag-skill/knowledge/危机干预/热线与即时求助/全国心理危机热线.txt',1413,'1.4 KB','全国心理危机热线与即时求助资源，包括12356全国统一心理援助热线、各省市心理援助热线、心理援助APP等资源介绍，以及热线使用技巧和即时求助指南。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(3,'心理援助热线与即时求助指南',4,73,'[\"热线\", \"12356\", \"心理援助\", \"即时求助\", \"危机干预\", \"全国热线\", \"省市热线\", \"危机电话\", \"自杀求助\"]','md','心理援助热线与即时求助指南.md','/rag-skill/knowledge/危机干预/热线与即时求助/心理援助热线与即时求助指南.md',6198,'6.1 KB','全国心理危机热线与即时求助资源，包括12356全国统一心理援助热线、各省市心理援助热线、心理援助APP等资源介绍，以及热线使用技巧和即时求助指南。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(4,'现场危机干预要点',4,74,'[\"现场干预\", \"心理急救\", \"PFA\", \"安全评估\", \"安全计划\", \"转介\", \"危机评估\", \"即时干预\", \"急诊处理\"]','md','现场危机干预要点.md','/rag-skill/knowledge/危机干预/现场干预要点/现场危机干预要点.md',7116,'6.9 KB','现场危机干预操作指南，包括心理急救（PFA）步骤、危机评估方法、安全计划制定及转介要点。适用于医护人员在急诊室、社区或学校等场景下对自杀危机个体的即时干预。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(5,'公益与社区心理资源',8,88,'[\"公益组织\", \"社区心理服务\", \"低费用咨询\", \"线上资源\", \"危机干预\", \"自助小组\", \"心理援助APP\"]','md','公益与社区心理资源.md','/rag-skill/knowledge/干预与求助资源/公益与社区资源/公益与社区心理资源.md',9442,'9.2 KB','公益心理组织和社区心理服务资源，包括：免费/低费用心理咨询、线上心理支持平台、危机干预公益组织。支持资源匮乏地区的心理求助需求。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(6,'心理援助热线资源',8,87,'[\"心理援助热线\", \"12356\", \"地方热线\", \"24小时热线\", \"危机热线\", \"自杀热线\"]','md','心理援助热线资源.md','/rag-skill/knowledge/干预与求助资源/心理援助热线/心理援助热线资源.md',8181,'8.0 KB','全国及地方心理援助热线资源，包括：12356全国统一心理援助热线、各省市心理危机热线、心理援助平台。热线是危机时刻的重要即时支持资源。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(7,'各省市心理机构',8,86,'[\"精神卫生中心\", \"精神科医院\", \"危机干预中心\", \"心理机构\", \"综合医院精神科\", \"社区心理服务\", \"三甲医院\", \"转介\"]','md','各省市心理机构.md','/rag-skill/knowledge/干预与求助资源/心理机构与医院/各省市心理机构.md',7117,'7.0 KB','各级精神卫生机构指南与全国心理机构名录，包括：三级甲等精神卫生中心、综合医院精神科、社区心理服务站。指导用户正确选择就医机构和理解转介流程。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(8,'心理卫生机构指南',8,86,'[\"精神卫生中心\", \"精神科医院\", \"危机干预中心\", \"心理机构\", \"综合医院精神科\", \"社区心理服务\", \"三甲医院\", \"转介\"]','md','心理卫生机构指南.md','/rag-skill/knowledge/干预与求助资源/心理机构与医院/心理卫生机构指南.md',10030,'9.8 KB','各级精神卫生机构指南与全国心理机构名录，包括：三级甲等精神卫生中心、综合医院精神科、社区心理服务站。指导用户正确选择就医机构和理解转介流程。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(9,'心理机构与医院',8,86,'[\"精神卫生中心\", \"精神科医院\", \"危机干预中心\", \"心理机构\", \"综合医院精神科\", \"社区心理服务\", \"三甲医院\", \"转介\"]','md','心理机构与医院.md','/rag-skill/knowledge/干预与求助资源/心理机构与医院/心理机构与医院.md',5298,'5.2 KB','各级精神卫生机构指南与全国心理机构名录，包括：三级甲等精神卫生中心、综合医院精神科、社区心理服务站。指导用户正确选择就医机构和理解转介流程。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(10,'心理健康标准',9,89,'[\"心理健康标准\", \"WHO十大标准\", \"风险等级\", \"心理弹性\", \"情绪健康\", \"社会功能\", \"评估维度\"]','md','心理健康标准.md','/rag-skill/knowledge/心理健康素养/心理健康标准/心理健康标准.md',1153,'1.1 KB','WHO心理健康十大标准与风险等级划分，包括：心理健康的定义、评估维度（情绪、认知、行为、社会功能）、风险等级判定（正常/关注/预警/危机）。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(11,'心理健康问题与应对',9,92,'[\"心理健康问题\", \"识别\", \"转介\", \"预防\", \"抑郁症\", \"焦虑症\", \"睡眠障碍\", \"物质滥用\", \"创伤后应激\"]','md','心理健康问题与应对.md','/rag-skill/knowledge/心理健康素养/心理健康问题与应对/心理健康问题与应对.md',4445,'4.3 KB','常见心理问题分类、识别与转介指南，包括：抑郁症、焦虑症、睡眠障碍、物质滥用等常见问题的识别要点、严重程度判断及转介建议。正确的识别和转介是自杀预防的重要环节。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(12,'情绪调节策略',9,91,'[\"情绪调节\", \"正念\", \"认知重评\", \"心理韧性\", \"接纳\", \"情绪表达\", \"问题解决\", \"正念减压\", \"MBSR\"]','md','情绪调节策略.md','/rag-skill/knowledge/心理健康素养/情绪调节策略/情绪调节策略.md',4669,'4.6 KB','循证情绪调节技术，包括：正念减压（MBSR）、认知重评、问题解决训练、情绪表达。良好的情绪调节能力是心理健康的保护因素，情绪调节困难是自杀风险信号。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(13,'认知扭曲与CBT',9,90,'[\"认知扭曲\", \"CBT\", \"认知行为疗法\", \"认知重构\", \"自动思维\", \"核心信念\", \"非黑即白\", \"灾难化\", \"读心术\"]','md','认知扭曲与CBT.md','/rag-skill/knowledge/心理健康素养/认知扭曲与CBT/认知扭曲与CBT.md',4254,'4.2 KB','十种认知扭曲类型与CBT认知行为疗法原理，包括：非黑即白思维、灾难化、读心术、情绪推理等。认知扭曲是抑郁和自杀风险的重要认知因素，CBT是循证治疗方法。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,2,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-22 00:18:25'),(14,'情绪识别与表达',5,76,'[\"情绪识别\", \"情绪粒度\", \"述情障碍\", \"情绪觉察\", \"TAS-20\", \"DBT技能\", \"情绪词汇\", \"命名情绪\"]','md','情绪识别与表达.md','/rag-skill/knowledge/情绪/情绪识别与表达/情绪识别与表达.md',6359,'6.2 KB','情绪识别与表达能力是情绪智力的基础，包括情绪觉察、命名、区分及表达技巧。述情障碍（情绪识别困难）是自杀风险的独立预测因子。本文档介绍DBT情绪觉察技能、情绪粒度概念及TAS-20述情障碍评估。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(15,'情绪调节方法',5,78,'[\"情绪调节\", \"DBT\", \"CBT\", \"认知重评\", \"正念\", \"痛苦耐受\", \"人际效能\", \"Gross模型\", \"DERS量表\", \"情绪调节困难\"]','md','情绪调节方法.md','/rag-skill/knowledge/情绪/情绪调节/情绪调节方法.md',11311,'11.0 KB','DBT/CBT循证情绪调节方法，包括Gross情绪调节过程模型、DBT四大技能模块（正念、痛苦耐受、情绪调节、人际效能）、CBT认知重构技术及正念情绪调节。本文档是自杀风险干预中情绪管理技能的核心参考。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(16,'负面情绪与风险',5,77,'[\"负面情绪\", \"焦虑\", \"抑郁\", \"愤怒\", \"恐惧\", \"情绪风暴\", \"心理韧性\", \"情绪调节困难\", \"自杀风险因素\"]','md','负面情绪与风险.md','/rag-skill/knowledge/情绪/负面情绪与风险/负面情绪与风险.md',8069,'7.9 KB','负面情绪（焦虑、抑郁、愤怒、恐惧等）与心理健康风险的关系分析。强烈、持续的负面情绪是自杀行为的重要风险因素。本文档介绍主要负面情绪类型、情绪风暴概念、心理韧性培养及风险信号识别。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(17,'抑郁与自杀风险关系',2,67,'[\"抑郁与自杀\", \"共病关系\", \"风险因素\", \"绝望感\", \"自杀意念\", \"认知扭曲\", \"风险量化\", \"保护因素\"]','md','抑郁与自杀风险关系.md','/rag-skill/knowledge/抑郁/抑郁与自杀风险/抑郁与自杀风险关系.md',6030,'5.9 KB','抑郁与自杀的共病关系分析，包括：抑郁作为自杀最重要的风险因素、机制（绝望感、认知扭曲）、风险量化（约60%的自杀死亡者患有抑郁症）、共病问题及保护因素。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(18,'抑郁症状识别与评估',2,66,'[\"抑郁症状\", \"心境障碍\", \"快感缺失\", \"兴趣减退\", \"绝望感\", \"DSM-5\", \"ICD-11\", \"诊断标准\", \"重度抑郁\", \"鉴别诊断\"]','md','抑郁症状识别与评估.md','/rag-skill/knowledge/抑郁/抑郁症状与评估/抑郁症状识别与评估.md',6713,'6.6 KB','抑郁症核心症状识别与评估方法，基于DSM-5/ICD-11诊断标准。包括：核心症状（情绪低落、兴趣减退、快感缺失）、附加症状（疲乏、自我价值感降低、自杀意念等）、严重程度分级及鉴别诊断。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(19,'抑郁症自助指南',2,66,'[\"抑郁症状\", \"心境障碍\", \"快感缺失\", \"兴趣减退\", \"绝望感\", \"DSM-5\", \"ICD-11\", \"诊断标准\", \"重度抑郁\", \"鉴别诊断\"]','txt','抑郁症自助指南.txt','/rag-skill/knowledge/抑郁/抑郁症状与评估/抑郁症自助指南.txt',1413,'1.4 KB','抑郁症核心症状识别与评估方法，基于DSM-5/ICD-11诊断标准。包括：核心症状（情绪低落、兴趣减退、快感缺失）、附加症状（疲乏、自我价值感降低、自杀意念等）、严重程度分级及鉴别诊断。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(20,'抑郁症识别与分类',2,66,'[\"抑郁症状\", \"心境障碍\", \"快感缺失\", \"兴趣减退\", \"绝望感\", \"DSM-5\", \"ICD-11\", \"诊断标准\", \"重度抑郁\", \"鉴别诊断\"]','md','抑郁症识别与分类.md','/rag-skill/knowledge/抑郁/抑郁症状与评估/抑郁症识别与分类.md',4532,'4.4 KB','抑郁症核心症状识别与评估方法，基于DSM-5/ICD-11诊断标准。包括：核心症状（情绪低落、兴趣减退、快感缺失）、附加症状（疲乏、自我价值感降低、自杀意念等）、严重程度分级及鉴别诊断。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(21,'抑郁症治疗与药物',2,68,'[\"抗抑郁药\", \"SSRIs\", \"SNRIs\", \"三环类\", \"CBT\", \"心理治疗\", \"住院治疗\", \"联合治疗\", \"维持治疗\", \"药物依从性\"]','md','抑郁症治疗与药物.md','/rag-skill/knowledge/抑郁/治疗与药物/抑郁症治疗与药物.md',5829,'5.7 KB','抑郁症治疗方案与药物使用指南，包括SSRIs/SNRIs等一线抗抑郁药、CBT心理治疗、联合治疗方案及住院指征。循证治疗可将自杀风险降低约60%。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(22,'抑郁量表说明与解读',2,69,'[\"PHQ-9\", \"BDI\", \"HAMD\", \"抑郁量表\", \"评分标准\", \"严重程度\", \"自杀意念\", \"临界值\", \"筛查工具\"]','md','抑郁量表说明与解读.md','/rag-skill/knowledge/抑郁/量表说明/抑郁量表说明与解读.md',4972,'4.9 KB','抑郁量表使用指南与解读，主要包括PHQ-9（患者健康问卷-9）、BDI（贝克抑郁量表）、HAMD（汉密尔顿抑郁量表）的评分标准、阈值解释及临床应用。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(23,'广泛性焦虑障碍识别与GAD-7评估',3,70,'[\"GAD-7\", \"广泛性焦虑\", \"惊恐障碍\", \"社交焦虑\", \"紧张\", \"担忧\", \"过度担忧\", \"共病\", \"评分标准\"]','md','广泛性焦虑障碍识别与GAD-7评估.md','/rag-skill/knowledge/焦虑/广泛性焦虑与识别/广泛性焦虑障碍识别与GAD-7评估.md',4949,'4.8 KB','广泛性焦虑障碍(GAD)识别与GAD-7量表评估，包括GAD定义（持续6个月以上的过度担忧）、诊断标准、与抑郁症的共病关系及GAD-7评分标准（5/10/15分为轻/中/重度焦虑）。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,6,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-22 00:22:03'),(24,'焦虑应对策略',3,72,'[\"焦虑应对\", \"正念\", \"放松训练\", \"CBT\", \"认知重构\", \"暴露疗法\", \"腹式呼吸\", \"渐进性肌肉放松\", \"DBT技能\"]','md','焦虑应对策略.md','/rag-skill/knowledge/焦虑/应对策略/焦虑应对策略.md',7463,'7.3 KB','循证焦虑应对方法与技能训练，包括：认知重构、正念减压、放松训练（腹式呼吸、渐进性肌肉放松）、暴露疗法及DBT情绪调节技能。焦虑应对技能是自杀风险干预的重要组成部分。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(25,'焦虑与睡眠障碍',3,71,'[\"焦虑与睡眠\", \"失眠\", \"心率加快\", \"呼吸急促\", \"睡眠障碍\", \"焦虑失眠共病\", \"HPA轴\", \"觉醒过度\"]','md','焦虑与睡眠障碍.md','/rag-skill/knowledge/焦虑/焦虑与睡眠/焦虑与睡眠障碍.md',6602,'6.4 KB','焦虑对睡眠的影响及相关障碍，包括：焦虑-失眠恶性循环、HPA轴激活机制、焦虑共病失眠的风险评估（失眠使自杀风险增加2倍）。改善睡眠是焦虑干预的重要组成部分。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(26,'PSQI_匹兹堡睡眠量表',6,82,'[\"PSQI\", \"匹兹堡\", \"睡眠质量\", \"失眠评估\", \"睡眠障碍\", \"睡眠效率\", \"催眠药物\", \"日间功能障碍\"]','docx','PSQI_匹兹堡睡眠量表.docx','/rag-skill/knowledge/睡眠与生理/PSQI量表/PSQI_匹兹堡睡眠量表.docx',1448,'1.4 KB','匹兹堡睡眠质量指数量表（PSQI），用于评估过去一个月的睡眠质量。PSQI总分>5提示存在睡眠问题。PSQI是自杀风险评估的重要辅助工具。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,2,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-22 10:09:58'),(27,'失眠与心理健康',6,79,'[\"失眠\", \"睡眠障碍\", \"心理问题\", \"HPA轴\", \"皮质醇\", \"失眠抑郁\", \"自杀风险\", \"睡眠卫生\", \"觉醒过度\"]','md','失眠与心理健康.md','/rag-skill/knowledge/睡眠与生理/失眠与心理/失眠与心理健康.md',9621,'9.4 KB','失眠与心理健康的关系，包括失眠-抑郁-自杀三元模型。约75%的抑郁症患者有失眠症状，失眠使自杀风险增加2倍。失眠既是心理健康问题的症状，也是其独立风险因素。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(28,'安眠药使用与副作用',6,80,'[\"安眠药\", \"苯二氮卓\", \"非苯二氮卓\", \"褪黑素\", \"依赖性\", \"戒断反应\", \"过量风险\"]','md','安眠药使用与副作用.md','/rag-skill/knowledge/睡眠与生理/安眠药与副作用/安眠药使用与副作用.md',8427,'8.2 KB','常用安眠药类型及副作用说明，包括：苯二氮卓类、非苯二氮卓类Z-drugs、褪黑素受体激动剂。需注意安眠药使用与自杀风险的复杂关系。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(29,'睡眠生理机制',6,81,'[\"睡眠周期\", \"快速眼动期\", \"NREM\", \"生理节律\", \"褪黑素\", \"皮质醇\", \"HPA轴\", \"昼夜节律\"]','md','睡眠生理机制.md','/rag-skill/knowledge/睡眠与生理/生理指标与睡眠/睡眠生理机制.md',10635,'10.4 KB','睡眠生理机制与生理指标，包括：睡眠周期（NREM 1-3期、REM）、昼夜节律、HPA轴激活、皮质醇节律。理解睡眠生理有助于识别失眠的神经生物学机制。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(30,'工具与高危手段认知',1,64,'[\"遗书\", \"告别信号\", \"轻生\", \"高危手段\", \"工具获取\", \"自杀方法\", \"致命性\", \"可及性\", \"危机表达\"]','md','工具与高危手段认知.md','/rag-skill/knowledge/自杀与自伤/危机表达与手段/工具与高危手段认知.md',4886,'4.8 KB','识别告别信号与高危手段认知，包括：遗书内容分析、告别语言识别、告别行为信号（突然赠送物品）、高危手段类型及工具可及性评估。正确识别危机表达是自杀预防的关键。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(31,'遗书与告别信号',1,64,'[\"遗书\", \"告别信号\", \"轻生\", \"高危手段\", \"工具获取\", \"自杀方法\", \"致命性\", \"可及性\", \"危机表达\"]','md','遗书与告别信号.md','/rag-skill/knowledge/自杀与自伤/危机表达与手段/遗书与告别信号.md',4719,'4.6 KB','识别告别信号与高危手段认知，包括：遗书内容分析、告别语言识别、告别行为信号（突然赠送物品）、高危手段类型及工具可及性评估。正确识别危机表达是自杀预防的关键。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(32,'何时求助与转介指南',1,65,'[\"求助\", \"转介\", \"医疗资源对接\", \"心理急救\", \"危机热线\", \"自杀未遂后转介\", \"社区精神科\", \"综合医院精神科\"]','md','何时求助与转介指南.md','/rag-skill/knowledge/自杀与自伤/求助与转介/何时求助与转介指南.md',5825,'5.7 KB','何时求助与转介流程指导，包括：识别需要专业帮助的信号、选择适当的求助渠道（社区/专科/急诊）、转介流程与资源对接。正确的求助和转介是自杀预防的关键保护因素。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(33,'自伤行为识别与干预',1,63,'[\"自伤\", \"NSSI\", \"非自杀性自伤\", \"自残\", \"刻板行为\", \"情绪调节困难\", \"DBT技能\", \"共病\", \"自伤频率\"]','md','自伤行为识别与干预.md','/rag-skill/knowledge/自杀与自伤/自伤与自残/自伤行为识别与干预.md',5147,'5.0 KB','非自杀性自伤(NSSI)识别与干预相关知识，包括：NSSI定义（切割、灼烧、撞击等无自杀意图的自伤）、与自杀行为的关系（共病率50%+）、风险因素、DBT技能训练等循证干预方法。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(34,'WHO_LIVE_LIFE自杀预防',1,62,'[\"自杀预防\", \"高危信号\", \"预警\", \"自杀意念\", \"风险因素\", \"保护因素\", \"WHO\", \"LIVE LIFE\", \"危险因素\"]','txt','WHO_LIVE_LIFE自杀预防.txt','/rag-skill/knowledge/自杀与自伤/自杀预防与教育/WHO_LIVE_LIFE自杀预防.txt',1200,'1.2 KB','自杀预防基础知识与高危信号识别，包括：WHO mhGAP自杀预防指南、LIVE LIFE干预策略、高危信号识别（言语/行为/环境信号）、自杀风险因素与保护因素。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(35,'自杀危害与认知',1,62,'[\"自杀预防\", \"高危信号\", \"预警\", \"自杀意念\", \"风险因素\", \"保护因素\", \"WHO\", \"LIVE LIFE\", \"危险因素\"]','md','自杀危害与认知.md','/rag-skill/knowledge/自杀与自伤/自杀预防与教育/自杀危害与认知.md',3464,'3.4 KB','自杀预防基础知识与高危信号识别，包括：WHO mhGAP自杀预防指南、LIVE LIFE干预策略、高危信号识别（言语/行为/环境信号）、自杀风险因素与保护因素。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,0,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 11:15:02'),(36,'高危信号识别指南',1,62,'[\"自杀预防\", \"高危信号\", \"预警\", \"自杀意念\", \"风险因素\", \"保护因素\", \"WHO\", \"LIVE LIFE\", \"危险因素\"]','md','高危信号识别指南.md','/rag-skill/knowledge/自杀与自伤/自杀预防与教育/高危信号识别指南.md',5618,'5.5 KB','自杀预防基础知识与高危信号识别，包括：WHO mhGAP自杀预防指南、LIVE LIFE干预策略、高危信号识别（言语/行为/环境信号）、自杀风险因素与保护因素。',NULL,NULL,NULL,'uploaded',0,0,0,NULL,4,NULL,'2026-04-20 11:09:47','2026-04-20 11:09:47','2026-04-20 22:34:04'),(37,'C-SSRS_自杀严重程度量表',7,85,'[\"C-SSRS\", \"哥伦比亚\", \"自杀意念\", \"行为\", \"风险评估\", \"自杀未遂\", \"致命