--
-- Table structure for table `knowledge_keywords`
--

DROP TABLE IF EXISTS `knowledge_keywords`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `knowledge_keywords` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `keyword` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关键词',
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '分类（可为空）',
  `color_class` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'bg-orange-100 text-orange-700' COMMENT '前端样式类',
  `is_hot` tinyint(1) DEFAULT '0' COMMENT '是否热门',
  `usage_count` int DEFAULT '0' COMMENT '使用次数',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `keyword` (`keyword`),
  KEY `idx_is_active` (`is_active`),
