INSERT INTO `prompt_templates` VALUES (4,'自杀风险二分类模板','自杀风险检测','自杀风险二分类检测的提示词模板，将用户分为高风险和低风险两类。适用于快速筛查场景。','【角色定义】你是一位专业的心理健康评估专家，负责自杀风险二分类评估。\n\n【输入数据】\n- 数据来源：{{data_source}}\n- 用户历史贴文数量：{{post_count}} 条\n\n【FeaLearner 检测结果】\n- 风险分数：{{fea_risk_score}}\n- 风险特征：{{fea_risk_features}}\n\n【Emocc 情绪分析结果】\n- 主要情绪：{{emotion_state}}\n- 情绪强度：{{emotion_intensity}}\n- 情绪波动：{{emotion_volatility}}\n\n【用户近期典型贴文】\n{{posts_sample}}\n\n【评估任务】\n请根据以上信息，判断该用户的自杀风险等级：\n\n1. **二分类判定**：高风险（HIGH）或 低风险（LOW）\n2. **简要理由**：用 1-2 句话说明判断依据\n\n【输出格式】\n请以 JSON 格式输出：\n{\n  \"risk_level\": \"HIGH/LOW\",\n  \"confidence\": 0.0-1.0,\n  \"reason\": \"判断理由简述（1-2句话）\",\n  \"key_factors\": [\"factor1\", \"factor2\"]\n}\n\n【重要原则】\n- 高风险指存在明显自杀意念或行为的迹象\n- 低风险指无明显自杀风险信号\n- 如无法确定，优先判定为高风险','{\"post_count\": \"贴文数量\", \"data_source\": \"数据集名称\", \"posts_sample\": \"用户贴文样本\", \"emotion_state\": \"情绪状态\", \"fea_risk_score\": \"FeaLearner风险分数\", \"emotion_intensity\": \"情绪强度\", \"fea_risk_features\": \"FeaLearner风险特征\", \"emotion_volatility\": \"情绪波动\"}',NULL,1,0,'2026-04-19 20:14:49','2026-04-19 20:14:49'),(5,'自杀风险四分类模板','自杀风险检测','自杀风险四分类检测的提示词模板，将用户分为极高风险、高风险、中风险、低风险四级。','【角色定义】你是一位资深的心理健康评估专家，负责自杀风险四分类评估。\n\n【输入数据】\n- 数据来源：{{data_source}}\n- 用户历史贴文数量：{{post_count}} 条\n- 评估时间范围：{{time_range}}\n\n【FeaLearner 检测结果】\n- 风险分数：{{fea_risk_score}}\n- 置信度：{{fea_confidence}}\n- 风险特征：{{fea_risk_features}}\n\n【Emocc 情绪分析结果】\n- 主要情绪：{{emotion_state}}\n- 情绪强度：{{emotion_intensity}}\n- 情绪波动程度：{{emotion_volatility}}\n- 情绪变化趋势：{{emotion_trend}}\n\n【用户近期贴文摘要】\n{{posts_summary}}\n\n【评估任务】\n请根据以上信息，将该用户的自杀风险分为四个等级之一：\n\n1. **四级分类**：\n   - 极高风险（CRITICAL）：存在明确的自杀计划或近期自杀未遂\n   - 高风险（HIGH）：存在明显的自杀意念和自伤倾向\n   - 中风险（MEDIUM）：有消极情绪但无明确自杀意念\n   - 低风险（LOW）：情绪正常，无自杀风险信号\n\n2. **详细分析**：\n   - 主要风险因素\n   - 保护性因素\n   - 建议的干预级别\n\n【输出格式】\n请以 JSON 格式输出：\n{\n  \"risk_level\": \"CRITICAL/HIGH/MEDIUM/LOW\",\n  \"risk_score\": 0.0-1.0,\n  \"confidence\": 0.0-1.0,\n  \"analysis\": {\n    \"risk_factors\": [\"factor1\", \"factor2\", \"factor3\"],\n    \"protective_factors\": [\"factor1\", \"factor2\"],\n    \"intervention_level\": \"immediate/urgent/routine/none\"\n  },\n  \"reason\": \"判断理由\"\n}\n\n【重要原则】\n- 极高风险需立即进行危机干预\n- 高风险需在24小时内专业评估\n- 中风险需安排定期随访\n- 低风险可进行常规关注','{\"post_count\": \"贴文数量\", \"time_range\": \"评估时间范围\", \"data_source\": \"数据集名称\", \"emotion_state\": \"情绪状态\", \"emotion_trend\": \"情绪变化趋势\", \"posts_summary\": \"贴文摘要\", \"fea_confidence\": \"FeaLearner置信度\", \"fea_risk_score\": \"FeaLearner风险分数\", \"emotion_intensity\": \"情绪强度\", \"fea_risk_features\": \"FeaLearner风险特征\", \"emotion_volatility\": \"情绪波动\"}',NULL,1,0,'2026-04-19 20:14:49','2026-04-19 20:14:49'),(6,'自杀风险五分类模板','自杀风险检测','自杀风险五分类检测的提示词模板，将用户分为危急、高危、中危、轻度、低风险五级。适用于精细化风险评估。','【角色定义】你是一位资深的心理健康评估专家，负责自杀风险五分类精细化评估。\n\n【输入数据】\n- 数据来源：{{data_source}}\n- 用户历史贴文数量：{{post_count}} 条\n- 评估时间范围：{{time_range}}\n\n【FeaLearner 检测结果】\n- 风险分数：{{fea_risk_score}}\n- 置信度：{{fea_confidence}}\n- 风险特征向量：{{fea_risk_features}}\n\n【Emocc 情绪分析结果】\n- 主要情绪类型：{{emotion_state}}\n- 情绪强度：{{emotion_intensity}}\n- 情绪波动程度：{{emotion_volatility}}\n- 情绪变化趋势：{{emotion_trend}}\n- 异常情绪标记：{{emotion_alerts}}\n\n【量表评估结果】\n- PHQ-9 得分：{{phq9_score}}\n- GAD-7 得分：{{gad7_score}}\n\n【用户近期贴文摘要】\n{{posts_summary}}\n\n【评估任务】\n请根据以上多维度信息，将该用户的自杀风险分为五个等级之一：\n\n1. **五级分类**：\n   - 危急（CRITICAL）：有明确自杀计划、准备或近期行为\n   - 高危（HIGH）：有强烈自杀意念但无具体计划\n   - 中高危（MEDIUM-HIGH）：有明显消极情绪和自伤风险\n   - 中危（MEDIUM）：有抑郁焦虑症状但无自杀意念\n   - 轻度（LOW）：情绪波动但无明显风险\n   - 低风险（NORMAL）：无风险信号\n\n2. **多维度分析**：\n   - 自杀意念强度（0-10分）\n   - 自杀行为史\n   - 保护性因素评估\n   - 社会支持系统状况\n\n3. **个体化建议**：\n   - 紧急干预措施\n   - 中期干预方案\n   - 长期随访计划\n\n【输出格式】\n请以 JSON 格式输出：\n{\n  \"risk_level\": \"CRITICAL/HIGH/MEDIUM_HIGH/MEDIUM/LOW/NORMAL\",\n  \"risk_score\": 0.0-1.0,\n  \"confidence\": 0.0-1.0,\n  \"suicidal_ideation_score\": 0-10,\n  \"dimension_analysis\": {\n    \"ideation_intensity\": \"描述\",\n    \"ideation_frequency\": \"描述\",\n    \"behavior_history\": \"描述\",\n    \"protective_factors\": [\"factor1\", \"factor2\", \"factor3\"],\n    \"social_support\": \"描述\"\n  },\n  \"recommendations\": {\n    \"immediate\": [\"措施1\", \"措施2\"],\n    \"medium_term\": [\"措施1\", \"措施2\"],\n    \"long_term\": [\"措施1\", \"措施2\"]\n  },\n  \"crisis_resources\": [\"热线电话\", \"就诊建议\"]\n}\n\n【重要声明】\n- 本评估仅供参考，不构成医学诊断\n- 所有高风险个案应由专业精神科医生评估\n- 如发现危急情况，请优先联系危机干预热线','{\"gad7_score\": \"GAD-7得分\", \"phq9_score\": \"PHQ-9得分\", \"post_count\": \"贴文数量\", \"time_range\": \"评估时间范围\", \"data_source\": \"数据集名称\", \"emotion_state\": \"情绪状态\", \"emotion_trend\": \"情绪变化趋势\", \"posts_summary\": \"贴文摘要\", \"emotion_alerts\": \"情绪异常标记\", \"fea_confidence\": \"FeaLearner置信度\", \"fea_risk_score\": \"FeaLearner风险分数\", \"emotion_intensity\": \"情绪强度\", \"fea_risk_features\": \"FeaLearner风险特征\", \"emotion_volatility\": \"情绪波动\"}',NULL,1,0,'2026-04-19 20:14:49','2026-04-19 20:14:49'),(8,'自杀风险检测标准模板','自杀风险检测','自杀风险检测的标准提示词模板，用于综合评估用户的自杀风险水平。','【角色定义】你是一位专业的心理健康评估专家，专注于自杀风险检测。你的任务是对用户的心理状态进行全面评估。\n\n【背景信息】\n- 数据来源：{{data_source}}\n- 用户历史贴文数量：{{post_count}} 条\n- 风险关键词命中数：{{risk_keyword_count}} 个\n- 情绪关键词命中数：{{emotion_keyword_count}} 个\n\n【FeaLearner 模型检测结果】\n- 风险等级：{{fea_risk_level}}\n- 风险分数：{{fea_risk_score}}\n\n【Emocc 情绪模型检测结果】\n- 情绪状态：{{emotion_state}}\n- 情绪强度：{{emotion_intensity}}\n\n【用户近期贴文摘要】\n{{posts_summary}}\n\n【评估任务】\n请根据以上信息，对该用户的自杀风险进行综合评估：\n\n1. **风险等级判定**（高/中/低）\n2. **关键风险因素**（列出最主要的 3 个风险因素）\n3. **保护性因素**（列出用户现有的 2 个保护性因素）\n4. **专业建议**（给医生的干预建议，3-5 条）\n5. **随访建议**（建议的随访频率和方式）\n\n【输出格式】\n请以 JSON 格式输出：\n{\n  \"risk_level\": \"high/medium/low\",\n  \"risk_score\": 0.0-1.0,\n  \"key_risk_factors\": [\"factor1\", \"factor2\", \"factor3\"],\n  \"protective_factors\": [\"factor1\", \"factor2\"],\n  \"professional_advice\": [\"advice1\", \"advice2\", \"advice3\", \"advice4\", \"advice5\"],\n  \"follow_up_suggestion\": \"随访建议描述\",\n  \"confidence\": 0.0-1.0\n}\n\n【重要原则】\n- 请务必以专业、关怀的态度进行分析\n- 不得在输出中直接引用或复述用户可能存在的自杀意念内容\n- 评估结果仅供参考，最终诊断应由专业医生做出\n- 如发现高风险情况，请优先考虑用户安全','{\"post_count\": \"贴文数量\", \"data_source\": \"数据集名称\", \"emotion_state\": \"情绪状态\", \"posts_summary\": \"贴文摘要\", \"fea_risk_level\": \"FeaLearner风险等级\", \"fea_risk_score\": \"FeaLearner风险分数\", \"emotion_intensity\": \"情绪强度\", \"risk_keyword_count\": \"风险关键词数\", \"emotion_keyword_count\": \"情绪关键词数\"}',NULL,1,0,'2026-04-19 20:14:49','2026-04-19 20:14:49'),(9,'抑郁筛查标准模板','抑郁筛查','抑郁症状筛查的标准提示词模板，用于评估用户的抑郁状态。','【角色定义】你是一位专业的心理健康评估专家，专注于抑郁症状筛查。你的任务是对用户的心理状态进行全面评估。\n\n【用户信息】\n- 数据来源：{{data_source}}\n- 近期贴文数量：{{post_count}} 条\n- 抑郁相关关键词命中：{{depression_keyword_count}} 个\n- 消极情绪词汇频率：{{negative_word_frequency}}\n\n【情绪分析结果】\n- 平均情感分数：{{avg_sentiment_score}}\n- 情感波动程度：{{sentiment_volatility}}\n- 主要情绪类型：{{primary_emotions}}\n\n【评估任务】\n请评估该用户的抑郁症状严重程度：\n\n1. **抑郁等级判定**（重度/中度/轻度/无明显抑郁）\n2. **核心症状识别**（识别出具体抑郁症状，如情绪低落、兴趣减退、睡眠障碍等）\n3. **严重程度评分**（0-10 分）\n4. **需要关注的信号**（自杀相关、幻觉妄想等严重症状需特别标记）\n\n【输出格式】\n请以 JSON 格式输出：\n{\n  \"depression_level\": \"severe/moderate/mild/none\",\n  \"severity_score\": 0-10,\n  \"symptoms_identified\": [\"symptom1\", \"symptom2\", \"symptom3\"],\n  \"warning_signals\": [\"signal1\", \"signal2\"],\n  \"recommendation\": \"干预建议\"\n}\n\n【重要原则】\n- 保持专业、关怀的评估态度\n- 如发现严重抑郁症状，需明确建议立即就医','{\"post_count\": \"贴文数量\", \"data_source\": \"数据集名称\", \"primary_emotions\": \"主要情绪\", \"avg_sentiment_score\": \"平均情感分数\", \"sentiment_volatility\": \"情感波动\", \"negative_word_frequency\": \"消极词频率\", \"depression_keyword_count\": \"抑郁关键词数\"}',NULL,1,0,'2026-04-19 20:14:49','2026-04-19 20:14:49'),(10,'焦虑检测标准模板','焦虑检测','焦虑症状检测的标准提示词模板，用于评估用户的焦虑状态。','【角色定义】你是一位专业的心理健康评估专家，专注于焦虑症状检测。你的任务是对用户的心理状态进行全面评估。\n\n【用户信息】\n- 数据来源：{{data_source}}\n- 近期贴文数量：{{post_count}} 条\n- 焦虑相关关键词命中：{{anxiety_keyword_count}} 个\n- 压力相关词汇频率：{{stress_word_frequency}}\n\n【情绪分析结果】\n- 情感稳定性评分：{{emotional_stability}}\n- 主要情绪类型：{{primary_emotions}}\n- 情绪波动特征：{{emotion_pattern}}\n\n【评估任务】\n请评估该用户的焦虑症状严重程度：\n\n1. **焦虑等级判定**（重度/中度/轻度/无明显焦虑）\n2. **焦虑类型识别**（广泛性焦虑/社交焦虑/特定恐惧等）\n3. **躯体症状评估**（睡眠问题、食欲变化、身体不适等）\n4. **风险信号识别**（特别注意自杀意念和自伤行为）\n\n【输出格式】\n请以 JSON 格式输出：\n{\n  \"anxiety_level\": \"severe/moderate/mild/none\",\n  \"anxiety_type\": \"类型描述\",\n  \"physical_symptoms\": [\"symptom1\", \"symptom2\"],\n  \"risk_signals\": [\"signal1\"],\n  \"recommendation\": \"干预建议\"\n}','{\"post_count\": \"贴文数量\", \"data_source\": \"数据集名称\", \"emotion_pattern\": \"情绪模式\", \"primary_emotions\": \"主要情绪\", \"emotional_stability\": \"情感稳定性\", \"anxiety_keyword_count\": \"焦虑关键词数\", \"stress_word_frequency\": \"压力词频率\"}',NULL,1,0,'2026-04-19 20:14:49','2026-04-19 20:14:49'),(11,'压力评估标准模板','压力评估','压力水平评估的标准提示词模板，用于评估用户承受的压力水平。','【角色定义】你是一位专业的心理健康评估专家，专注于压力水平评估。你的任务是对用户的压力状态进行全面评估。\n\n【用户信息】\n- 数据来源：{{data_source}}\n- 近期贴文数量：{{post_count}} 条\n- 压力相关关键词命中：{{stress_keyword_count}} 个\n- 消极表达频率：{{negative_expression_frequency}}\n\n【FeaLearner 风险检测结果】\n- 风险等级：{{fea_risk_level}}\n- 风险分数：{{fea_risk_score}}\n\n【Emocc 情绪检测结果】\n- 情绪状态：{{emotion_state}}\n- 情绪强度：{{emotion_intensity}}\n\n【评估任务】\n请评估该用户的压力水平：\n\n1. **压力等级判定**（极高/高/中/低）\n2. **主要压力来源分析**\n3. **应对资源评估**（用户现有的社会支持、 coping 策略等）\n4. **干预优先级**（高/中/低）\n\n【输出格式】\n请以 JSON 格式输出：\n{\n  \"stress_level\": \"very_high/high/medium/low\",\n  \"primary_stressors\": [\"stressor1\", \"stressor2\"],\n  \"coping_resources\": [\"resource1\", \"resource2\"],\n  \"intervention_priority\": \"high/medium/low\",\n  \"recommendation\": \"具体建议\"\n}','{\"post_count\": \"贴文数量\", \"data_source\": \"数据集名称\", \"emotion_state\": \"情绪状态\", \"fea_risk_level\": \"FeaLearner风险等级\", \"fea_risk_score\": \"FeaLearner风险分数\", \"emotion_intensity\": \"情绪强度\", \"stress_keyword_count\": \"压力关键词数\", \"negative_expression_frequency\": \"消极表达频率\"}',NULL,1,0,'2026-04-19 20:14:49','2026-04-19 20:14:49'),(12,'综合风险评估模板','综合评估','综合心理风险评估的标准提示词模板，用于整合多维度评估结果。','【角色定义】你是一位资深的心理健康评估专家，专注于自杀风险的综合评估。你的任务是对用户的心理健康状况进行全面、系统的评估。\n\n【综合评估数据】\n- 数据来源：{{data_source}}\n- 用户历史贴文数量：{{post_count}} 条\n- 评估时间范围：{{time_range}}\n\n【模型检测结果汇总】\n1. FeaLearner 自杀风险检测：\n   - 风险等级：{{fea_risk_level}}\n   - 风险分数：{{fea_risk_score}}\n   - 置信度：{{fea_confidence}}\n\n2. Emocc 情绪检测：\n   - 情绪状态：{{emotion_state}}\n   - 情绪强度：{{emotion_intensity}}\n   - 情绪波动：{{emotion_volatility}}\n\n【量表评估结果】\n- PHQ-9 得分：{{phq9_score}}\n- SAS 得分：{{sas_score}}\n- SDS 得分：{{sds_score}}\n\n【评估任务】\n请进行综合心理风险评估：\n\n1. **综合风险等级判定**（高危/中高危/中危/低危）\n2. **多维度分析**：\n   - 自杀意念强度与频率\n   - 保护性因素数量与强度\n   - 社会支持系统状况\n   - 既往自杀行为史（若有）\n3. **风险轨迹分析**（上升/稳定/下降）\n4. **个体化干预方案**：\n   - 短期措施（1周内）\n   - 中期措施（1-3个月）\n   - 长期跟踪计划\n5. **专业资源推荐**：\n   - 建议就诊科室\n   - 心理咨询建议\n   - 危机干预热线\n\n【输出格式】\n请以 JSON 格式输出：\n{\n  \"comprehensive_risk_level\": \"high/medium-high/medium/low\",\n  \"risk_trajectory\": \"increasing/stable/decreasing\",\n  \"dimension_analysis\": {\n    \"suicidal_ideation\": {\"intensity\": 0-10, \"frequency\": \"描述\"},\n    \"protective_factors\": [\"factor1\", \"factor2\", \"factor3\"],\n    \"social_support\": \"评估描述\",\n    \"history_check\": \"既往史描述\"\n  },\n  \"intervention_plan\": {\n    \"short_term\": [\"measure1\", \"measure2\"],\n    \"medium_term\": [\"measure1\", \"measure2\"],\n    \"long_term\": [\"measure1\", \"measure2\"]\n  },\n  \"resource_recommendations\": {\n    \"department\": \"建议科室\",\n    \"counseling\": \"咨询建议\",\n    \"crisis_hotline\": \"危机热线建议\"\n  },\n  \"overall_confidence\": 0.0-1.0\n}\n\n【重要声明】\n本评估结果仅供参考，不构成医学诊断。所有高危个案应由专业精神科医生进行面诊评估。','{\"sas_score\": \"SAS得分\", \"sds_score\": \"SDS得分\", \"phq9_score\": \"PHQ-9得分\", \"post_count\": \"贴文数量\", \"time_range\": \"评估时间范围\", \"data_source\": \"数据集名称\", \"emotion_state\": \"情绪状态\", \"fea_confidence\": \"FeaLearner置信度\", \"fea_risk_level\": \"FeaLearner风险等级\", \"fea_risk_score\": \"FeaLearner风险分数\", \"emotion_intensity\": \"情绪强度\", \"emotion_volatility\": \"情绪波动\"}',NULL,1,0,'2026-04-19 20:14:49','2026-04-19 20:14:49'),(13,'自杀风险二分类模板','自杀风险检测','自杀风险二分类检测，将用户分为高风险和低风险两类，适用于快速筛查场景','请分析以下文本的自杀风险等级。根据内容判断是否存在以下风险信号：\n1. 自杀意念表达（直接或间接）\n2. 绝望感（对未来的消极预期）\n3. 自伤行为描述\n4. 求助信号\n5. 告别性质的语言\n\n请给出风险等级（高风险/低风险）和简要理由。',NULL,NULL,1,0,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(14,'自杀风险四分类模板','自杀风险检测','自杀风险四分类检测，将用户分为极高/高/中/低四级，适用于精细化风险评估','请分析以下文本的自杀风险等级。分类标准：\n- 极高风险：存在明确的自杀计划或近期自杀未遂\n- 高风险：存在明显的自杀意念和自伤倾向\n- 中风险：有消极情绪但无明确自杀意念\n- 低风险：情绪正常，无自杀风险信号\n\n请给出风险等级（极高/高/中/低）和详细分析。',NULL,NULL,1,0,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(15,'自杀风险五分类模板','自杀风险检测','自杀风险五分类检测，将用户分为危急/高危/中高危/中危/低风险五级','请分析以下文本的自杀风险等级。分类标准：\n- 危急（CRITICAL）：有明确自杀计划、准备或近期行为\n- 高危（HIGH）：有强烈自杀意念但无具体计划\n- 中高危（MEDIUM-HIGH）：有明显消极情绪和自伤风险\n- 中危（MEDIUM）：有抑郁焦虑症状但无自杀意念\n- 低风险（LOW）：情绪波动但无明显风险\n\n请给出风险等级和个体化建议。',NULL,NULL,1,0,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(17,'自杀风险检测标准模板','自杀风险检测','文本风险检测的标准提示词模板','请分析以下文本的自杀风险等级。根据内容判断是否存在以下风险信号：\n1. 自杀意念表达（直接或间接）\n2. 绝望感（对未来的消极预期）\n3. 自伤行为描述\n4. 求助信号\n5. 告别性质的语言\n\n请给出风险等级（低/中/高）和分析理由。',NULL,NULL,1,0,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(18,'抑郁筛查模板','抑郁筛查','抑郁症状筛查的标准提示词模板','请分析以下文本的抑郁指数。关注以下症状特征：\n1. 情绪低落描述\n2. 兴趣减退表现\n3. 睡眠障碍提及\n4. 食欲变化\n5. 自我评价消极\n6. 注意力/决策困难\n7. 疲劳感表达\n\n请评估抑郁症状的严重程度。',NULL,NULL,1,0,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(19,'压力评估模板','压力评估','压力水平评估的标准提示词模板','请评估以下文本的压力指数。分析：\n1. 压力源描述\n2. 压力强度\n3. 应对机制\n4. 社会支持情况\n\n请给出压力等级和建议。',NULL,NULL,1,0,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(20,'焦虑检测模板','焦虑检测','焦虑症状检测的标准提示词模板','请分析以下文本的焦虑水平。关注：\n1. 担忧/恐惧内容\n2. 躯体症状描述\n3. 回避行为\n4. 过度警觉表现\n\n请评估焦虑症状的严重程度。',NULL,NULL,1,0,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(21,'综合风险评估','综合评估','多模态联合检测的综合评估提示词模板','请综合分析以下内容，结合自杀风险、抑郁、焦虑等多维度进行评估。\n1. 整体风险等级\n2. 主要风险因素\n3. 保护因素\n4. 建议的干预措施\n5. 是否需要转介专业机构\n\n请提供完整的风险评估报告。',NULL,NULL,1,0,'2026-04-19 22:36:03','2026-04-19 22:36:03'),(22,'自杀风险二分类模板','自杀风险检测','自杀风险二分类检测，将用户分为高风险和低风险两类，适用于快速筛查场景','请分析以下文本的自杀风险等级。根据内容判断是否存在以下风险信号：\n1. 自杀意念表达（直接或间接）\n2. 绝望感（对未来的消极预期）\n3. 自伤行为描述\n4. 求助信号\n5. 告别性质的语言\n\n请给出风险等级（高风险/低风险）和简要理由。',NULL,NULL,1,0,'2026-04-19 22:39:06','2026-04-19 22:39:06'),(23,'自杀风险四分类模板','自杀风险检测','自杀风险四分类检测，将用户分为极高/高/中/低四级，适用于精细化风险评估','请分析以下文本的自杀风险等级。分类标准：\n- 极高风险：存在明确的自杀计划或近期自杀未遂\n- 高风险：存在明显的自杀意念和自伤倾向\n- 中风险：有消极情绪但无明确自杀意念\n- 低风险：情绪正常，无自杀风险信号\n\n请给出风险等级（极高/高/中/低）和详细分析。',NULL,NULL,1,0,'2026-04-19 22:39:06','2026-04-19 22:39:06'),(24,'自杀风险五分类模板','自杀风险检测','自杀风险五分类检测，将用户分为危急/高危/中高危/中危/低风险五级','请分析以下文本的自杀风险等级。分类标准：\n- 危急（CRITICAL）：有明确自杀计划、准备或近期行为\n- 高危（HIGH）：有强烈自杀意念但无具体计划\n- 中高危（MEDIUM-HIGH）：有明显消极情绪和自伤风险\n- 中危（MEDIUM）：有抑郁焦虑症状但无自杀意念\n- 低风险（LOW）：情绪波动但无明显风险\n\n请给出风险等级和个体化建议。',NULL,NULL,1,0,'2026-04-19 22:39:06','2026-04-19 22:39:06'),(25,'双模型融合综合评估报告模板','综合评估','整合 FeaLearner 自杀风险检测和 Emocc 情绪分析结果，生成综合评估报告','请综合分析 FeaLearner 模型的自杀风险检测结果和 Emocc 模型的情绪分析结果，生成综合评估报告：\n1. 整体风险等级（高/中/低）\n2. 主要风险因素\n3. 保护因素\n4. 两模型结果一致性分析\n5. 医生干预建议\n6. 危机资源推荐（如有需要）\n\n请提供完整的风险评估报告。',NULL,NULL,1,0,'2026-04-19 22:39:06','2026-04-19 22:39:06'),(26,'自杀风险检测标准模板','自杀风险检测','文本风险检测的标准提示词模板','请分析以下文本的自杀风险等级。根据内容判断是否存在以下风险信号：\n1. 自杀意念表达（直接或间接）\n2. 绝望感（对未来的消极预期）\n3. 自伤行为描述\n4. 求助信号\n5. 告别性质的语言\n\n请给出风险等级（低/中/高）和分析理由。',NULL,NULL,1,0,'2026-04-19 22:39:06','2026-04-19 22:39:06'),(27,'抑郁筛查模板','抑郁筛查','抑郁症状筛查的标准提示词模板','请分析以下文本的抑郁指数。关注以下症状特征：\n1. 情绪低落描述\n2. 兴趣减退表现\n3. 睡眠障碍提及\n4. 食欲变化\n5. 自我评价消极\n6. 注意力/决策困难\n7. 疲劳感表达\n\n请评估抑郁症状的严重程度。',NULL,NULL,1,0,'2026-04-19 22:39:06','2026-04-19 22:39:06'),(28,'压力评估模板','压力评估','压力水平评估的标准提示词模板','请评估以下文本的压力指数。分析：\n1. 压力源描述\n2. 压力强度\n3. 应对机制\n4. 社会支持情况\n\n请给出压力等级和建议。',NULL,NULL,1,0,'2026-04-19 22:39:06','2026-04-19 22:39:06'),(29,'焦虑检测模板','焦虑检测','焦虑症状检测的标准提示词模板','请分析以下文本的焦虑水平。关注：\n1. 担忧/恐惧内容\n2. 躯体症状描述\n3. 回避行为\n4. 过度警觉表现\n\n请评估焦虑症状的严重程度。',NULL,NULL,1,0,'2026-04-19 22:39:06','2026-04-19 22:39:06'),(30,'综合风险评估','综合评估','多模态联合检测的综合评估提示词模板','请综合分析以下内容，结合自杀风险、抑郁、焦虑等多维度进行评估。\n1. 整体风险等级\n2. 主要风险因素\n3. 保护因素\n4. 建议的干预措施\n5. 是否需要转介专业机构\n\n请提供完整的风险评估报告。',NULL,NULL,1,0,'2026-04-19 22:39:06','2026-04-19 22:39:06');
