DROP TABLE IF EXISTS `scale_definitions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `scale_definitions` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `scale_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '量表代码',
  `scale_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '量表名称简称',
  `full_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '量表完整名称',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'depression' COMMENT '量表类别',
  `question_count` int NOT NULL COMMENT '题目数量',
  `max_score` int NOT NULL COMMENT '满分',
  `threshold` int DEFAULT '10' COMMENT '阈值',
  `estimated_time` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '约5分钟' COMMENT '预计完成时间',
  `color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '#9b59b6' COMMENT '主题色',
  `bg_color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '#9b59b6' COMMENT '背景色',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `sort_order` int DEFAULT '0' COMMENT '排序顺序',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `scale_code` (`scale_code`),
  KEY `idx_scale_code` (`scale_code`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='量表定义表（最小元数据）';
