DROP TABLE IF EXISTS `scale_tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `scale_tasks` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `task_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务名称',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `user_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '脱敏用户标识',
  `user_alias` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '匿名用户' COMMENT '用户昵称',
  `archive_id` bigint DEFAULT NULL COMMENT '关联档案ID',
  `data_source` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据来源',
  `data_source_label` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据来源显示名称',
  `scale_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '量表代码（冗余存储）',
  `scale_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '量表代码',
  `scale_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '量表名称简称',
  `scale_full_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '量表完整名称',
  `scale_category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '量表类别',
  `scale_color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '#C19A83' COMMENT '主题色',
  `scale_bg_color` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '#C19A83' COMMENT '背景色',
  `total_questions` int DEFAULT '0' COMMENT '总题数（冗余存储）',
  `status` enum('pending','in_progress','completed','expired') COLLATE utf8mb4_unicode_ci DEFAULT 'pending' COMMENT '任务状态',
  `progress` int DEFAULT '0' COMMENT '进度',
  `answered_questions` int DEFAULT '0' COMMENT '已答题数',
  `answers` json DEFAULT NULL COMMENT '答案列表',
  `total_score` int DEFAULT NULL COMMENT '总分',
  `risk_level` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '风险等级',
  `assessment_result` text COLLATE utf8mb4_unicode_ci COMMENT '评估结果详情',
  `started_at` datetime DEFAULT NULL COMMENT '开始时间',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `expired_at` datetime DEFAULT NULL COMMENT '过期时间',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_task_name` (`task_name`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_user_hash` (`user_hash`),
  KEY `idx_archive_id` (`archive_id`),
  KEY `idx_data_source` (`data_source`),
  KEY `idx_scale_id` (`scale_id`),
  KEY `idx_scale_code` (`scale_code`),
  KEY `idx_scale_category` (`scale_category`),
  KEY `idx_status` (`status`),
  KEY `idx_risk_level` (`risk_level`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='量表评估任务表';
/*!40101 SET character_set_client = @saved_cs_client */;

